WITH valid_transactions AS (SELECT * FROM transactions WHERE amount < 1200), transactions_stats AS (SELECT txn_type, merchant, MIN(amount) AS min_amount, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(merchant))) AS merchant_values FROM valid_transactions GROUP BY txn_type, merchant) SELECT txn_type, merchant, merchant_values FROM transactions_stats WHERE min_amount >= 2200 ORDER BY txn_type;
